In this Business Rule, a breakpoint is set on the line marked below. What happens when an Incident update fires this rule?

(function executeRule(current, previous) {
    var newPriority = current.getValue('priority');   // <- breakpoint
    if (newPriority == 1) {
        current.work_notes = 'Escalated.';
    }
})(current, previous);
